const snowLeopardSheet=new Image();snowLeopardSheet.assetSrc='assets/snow-leopard-v1.png';
function beginSnowLeopard(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'snowLeopardLead',bespoke:true,windup:1.2,origin:{x:e.x,y:e.y},last:{x:e.x,y:e.y},playerLast:{x:p.x,y:p.y},vx:0,vy:0,target:{x:p.x,y:p.y},locked:false,blocked:false,landed:false,hit:false};}
function aimSnowLeopard(a,dt){let vx=(p.x-a.playerLast.x)/dt,vy=(p.y-a.playerLast.y)/dt,speed=Math.hypot(vx,vy);if(speed>320){vx*=320/speed;vy*=320/speed;}let blend=1-Math.exp(-10*dt);a.vx+=(vx-a.vx)*blend;a.vy+=(vy-a.vy)*blend;a.playerLast={x:p.x,y:p.y};let dx=a.vx*.95,dy=a.vy*.95,lead=Math.hypot(dx,dy);if(lead>300){dx*=300/lead;dy*=300/lead;}let target={x:p.x+dx,y:p.y+dy},tx=target.x-a.origin.x,ty=target.y-a.origin.y,d=Math.hypot(tx,ty);if(d>520)target={x:a.origin.x+tx/d*520,y:a.origin.y+ty/d*520};a.target=target;}
function lockSnowLeopard(a){let dx=a.target.x-a.origin.x,dy=a.target.y-a.origin.y,d=Math.hypot(dx,dy),target={...a.origin};for(let r=6;r<d+6;r+=6){let step=Math.min(r,d),q={x:a.origin.x+dx/(d||1)*step,y:a.origin.y+dy/(d||1)*step};if(!passable(q.x,q.y,18)||!lineClear(target,q,18))break;target=q;}a.target=target;a.locked=true;}
const snowLeopardAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r5e5')return snowLeopardAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='snowLeopardLead'){
  e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=350&&clear){beginSnowLeopard(e);return;}e.state='idle';if(d>850&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,135*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;
 }
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.4;return;}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;if(!a.locked){aimSnowLeopard(a,dt);if(e.elapsed>=.6)lockSnowLeopard(a);let dx=a.target.x-e.x,dy=a.target.y-e.y;e.facing=dx-dy<0?-1:1;}
 if(a.locked&&e.elapsed>=1.2&&!a.blocked){let t=e.elapsed>=1.55?1:Math.max(0,(e.elapsed-1.2)/.35),q={x:a.origin.x+(a.target.x-a.origin.x)*t,y:a.origin.y+(a.target.y-a.origin.y)*t},dx=q.x-e.x,dy=q.y-e.y,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/6));for(let i=0;i<n;i++){let next={x:e.x+dx/n,y:e.y+dy/n};if(!passable(next.x,next.y,18)||!lineClear(e,next,18)){a.blocked=true;break;}e.x=next.x;e.y=next.y;}a.last={x:e.x,y:e.y};a.landed=t===1&&!a.blocked&&dist(e,a.target)<.01;}
 if(!a.hit&&e.elapsed>=1.55){a.hit=true;e.struck=true;if(a.landed&&dist(p,a.target)<=70+1e-8&&lineClear(a.target,p))hurt(64);if(a.landed){burst(e.x,e.y,70,'#bbe5f4');playSound('slash',e.x,e.y);}}
 if(e.elapsed>=2.3){e.attack=null;e.state='idle';e.t=2.1;}
};
const snowLeopardDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r5e5'||!snowLeopardSheet.complete||!snowLeopardSheet.naturalWidth||!snowLeopardSheet.naturalHeight)return snowLeopardDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='snowLeopardLead')f={row:2,col:e.elapsed<.6?0:e.elapsed<1.2?1:e.elapsed<1.55?2:3};let q=project(e.x,e.y),sw=snowLeopardSheet.naturalWidth/4,sh=snowLeopardSheet.naturalHeight/3,w=230,h=w*sh/sw,anchor=[.88,.82,.73][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,snowLeopardSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(snowLeopardSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const snowLeopardSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r5e5'?145:snowLeopardSizeBase(e);
const snowLeopardGroundBase=drawGroundEffects;drawGroundEffects=()=>{snowLeopardGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r5e5'):enemies)){let a=e.attack;if(e.species!=='r5e5'||e.hp<=0||a?.pattern!=='snowLeopardLead'||a.hit||a.blocked||!visibleAt(a.target.x,a.target.y))continue;groundRing(a.target.x,a.target.y,70,a.locked?'#efa56c':'#b1c8e4',a.locked?3:1);if(a.locked)groundRing(a.target.x,a.target.y,70*Math.max(0,1-(e.elapsed-.6)/.6),'#ffe4bb',1);}};
